## Why This Is Asked

Explores a new DP angle: selecting exactly k non-overlapping substrings with a per-substring palindrome-anagram constraint, requiring fast feasibility testing via prefix masks and reconstruction.

## Key Concepts

- Palindromable substrings via 26-bit parity mask
- Prefix XOR to test s[l..r] in O(1)
- DP over i and t with transitions from p-1
- Backpointer reconstruction; space optimization with rolling arrays
- Time complexity: O(n^2 k)

## Code Example

```javascript
function maxLenPalAnagram(s, k) {
  const n = s.length;
  const pref = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) pref[i] = pref[i - 1] ^ (1 << (s.charCodeAt(i - 1) - 97));
  function popcount(x) { let c = 0; while (x) { x &= x - 1; c++; } return c; }
  function canPal(l, r) {
    return popcount(pref[r] ^ pref[l - 1]) <= 1;
  }
  // DP skeleton: dp[i][t] = max total length through i with t substrings
}
```

## Follow-up Questions

- How to optimize to near O(nk) for special input patterns? 
- How to reconstruct actual substrings efficiently and handle ties?

## Why This Is Asked
This problem tests dynamic programming on partitioning with a non-linear cost function (distinct character count). It's concrete, implementable, and scales well to typical interview constraints.

## Key Concepts
- DP over prefixes and partition count
- Precomputing distinct character counts for all substrings (O(n²) with two pointers)
- Reconstruction via parent pointers
- Time/space trade-offs

## Code Example
```javascript
function maxPartitionDistinct(s, k) {
  const n = s.length;
  const dist = Array.from({ length: n }, () => Array(n).fill(0));

  for (let i = 0; i < n; i++) {
    const seen = new Set();
    for (let j = i; j < n; j++) {
      seen.add(s[j]);
      dist[i][j] = seen.size;
    }
  }

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const prev = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= Math.min(i, k); t++) {
      for (let j = t - 1; j < i; j++) {
        const val = dp[j][t - 1] + dist[j][i - 1];
        if (val > dp[i][t]) {
          dp[i][t] = val;
          prev[i][t] = j;
        }
      }
    }
  }

  const partitions = [];
  let [i, t] = [n, k];
  while (t > 0) {
    const j = prev[i][t];
    partitions.unshift([j, i - 1]);
    i = j;
    t--;
  }

  return { value: dp[n][k], partitions };
}
```

## Why This Is Asked
Tests DP partitioning with a non-sum objective and reconstruction requirements.

## Key Concepts
- DP over partitions with dp[i][t]
- Precomputing max-min for all subarrays
- Path reconstruction via parent pointers

## Code Example
```javascript
function maxMinSubarrayVal(arr){
  const n = arr.length;
  const maxVal = Array.from({length:n}, ()=>Array(n).fill(0));
  const minVal = Array.from({length:n}, ()=>Array(n).fill(0));
  for(let i=0;i<n;i++){
    let curMax = arr[i], curMin = arr[i];
    for(let j=i;j<n;j++){
      curMax = Math.max(curMax, arr[j]);
      curMin = Math.min(curMin, arr[j]);
      maxVal[i][j] = curMax;
      minVal[i][j] = curMin;
    }
  }
  const val = (l,r)=> maxVal[l][r] - minVal[l][r];
  return val;
}

function bestPartition(arr, k){
  const n = arr.length;
  const val = maxMinSubarrayVal(arr);
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const parent = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for(let i=1;i<=n;i++) dp[i][1] = val(0,i-1);
  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<=i-1;j++){
        const cand = dp[j][t-1] + val(j, i-1);
        if(cand > dp[i][t]){ dp[i][t] = cand; parent[i][t]=j; }
      }
    }
  }
  // reconstruct
  let blocks = [];
  let i=n, t=k;
  while(t>0){
    const j = parent[i][t];
    blocks.push([j, i-1]);
    i = j; t--;
  }
  blocks.reverse();
  return {value: dp[n][k], blocks};
}
```

## Follow-up Questions
- How to optimize memory to O(nk)?
- Can you handle ties deterministically for block reconstruction?

## Why This Problem Is Asked
This classic problem evaluates your ability to design clean DP states for interval selection with reconstruction requirements. It strikes the right balance—accessible to beginners while effectively testing state structuring and backtracking skills.

## Key Concepts
- **dp[i][t]** manages selections across the first i elements with at most t subarrays
- **local[i][t]** distinguishes between extending an existing subarray and starting a new one
- Backtracking through the DP table to reconstruct segment boundaries

## Code Example
```javascript
function maxSumSubarrays(nums, k) {
    if (!nums.length || k <= 0) return { maxSum: 0, subarrays: [] };

    const n = nums.length;
    const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(0));
    const local = Array.from({ length: n + 1 }, () => Array(k + 1).fill(0));
    const endIdx = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));

    for (let i = 1; i <= n; i++) {
        for (let t = 1; t <= Math.min(k, i); t++) {
            local[i][t] = Math.max(
                local[i - 1][t] + nums[i - 1],
                dp[i - 1][t - 1] + nums[i - 1]
            );
            if (local[i][t] === dp[i - 1][t - 1] + nums[i - 1]) {
                endIdx[i][t] = i - 1;
            }
            dp[i][t] = dp[i - 1][t] >= local[i][t] ? dp[i - 1][t] : local[i][t];
        }
    }

    const subarrays = [];
    let j = n, t = k;
    while (t > 0 && j > 0) {
        if (endIdx[j][t] !== -1) {
            let start = endIdx[j][t];
            while (start > 0 && endIdx[start][t] !== -1) start--;
            subarrays.unshift([start, endIdx[j][t]]);
            j = start;
            t--;
        } else {
            break;
        }
    }

    return { maxSum: dp[n][k], subarrays };
}
```

## Why This Is Asked
DP over subsequences with a fixed length captures real-world problems like quantizing sequences while minimizing total variation; it tests state definition, reconstruction, and complexity trade-offs.

## Key Concepts
- DP state: last index and length; - Transition: O(n) over prior indices; - Reconstruction via parent pointers; - Complexity: O(n^2 k) time, O(nk) space.

## Code Example
```javascript
function minCostSubsequence(A, k) {
  const n = A.length, INF = 1e18;
  const dp = Array.from({length: n}, ()=> Array(k+1).fill(INF));
  const par = Array.from({length: n}, ()=> Array(k+1).fill(-1));
  for (let i=0;i<n;i++) dp[i][1] = 0;
  for (let t=2;t<=k;t++) {
    for (let i=0;i<n;i++) {
      for (let j=0;j<i;j++) {
        const val = dp[j][t-1] + Math.abs(A[i]-A[j]);
        if (val < dp[i][t]) { dp[i][t] = val; par[i][t] = j; }
      }
    }
  }
  let best = INF, last = -1;
  for (let i=0;i<n;i++) if (dp[i][k] < best) { best = dp[i][k]; last = i; }
  const idx = Array(k);
  let t = k, cur = last;
  while (t>=1) { idx[t-1] = cur; cur = par[cur][t]; t--; }
  return {cost: best, indices: idx};
}
```

## Why This Is Asked
Tests concrete DP skills on string partitioning with reconstruction; approachable for beginners yet non-trivial.

## Key Concepts
- dp[i][t]: maximum sum for first i digits split into t parts
- val(j,i): integer value of s[j..i-1] (leading zeros allowed)
- transition: dp[i][t] = max_{j ∈ [t-1..i-1]} dp[j][t-1] + val(j,i)
- reconstruction: track prev to recover split indices
- complexity: O(n²k) time, O(nk) space; use BigInt for large results

## Code Example
```javascript
function maxSumSplit(s, k){
  const n = s.length;
  const val = (a,b)=> BigInt(s.slice(a,b));
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(-1n));
  const prev = Array.from({length: n+1}, () => Array(k+1).fill(-1));

  for(let i=1;i<=n;i++){
    dp[i][1] = val(0,i);
  }

  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<i;j++){
        const candidate = dp[j][t-1] + val(j,i);
        if(candidate > dp[i][t]){
          dp[i][t] = candidate;
          prev[i][t] = j;
        }
      }
    }
  }

  // Reconstruct splits
  const splits = [];
  let curr = n, parts = k;
  while(parts > 1){
    const j = prev[curr][parts];
    splits.push(j);
    curr = j;
    parts--;
  }
  splits.reverse();

  return {maxSum: dp[n][k], splits};
}
```

