## Why This Is Asked
This question tests building a DP over subsequences with constraints, requiring a clear state definition and transition over previous indices, plus reconstruction capabilities.

## Key Concepts
- Subsequence DP with constraints
- State dp[i] and parent tracking
- Time/space analysis and reconstruction

## Code Example
```javascript
function maxSubseqWithDiff(a, d) {
  const n = a.length;
  const dp = Array(n).fill(0);
  const par = Array(n).fill(-1);
  let best = -Infinity, bestIdx = -1;

  for (let i = 0; i < n; i++) {
    dp[i] = a[i];
    for (let j = 0; j < i; j++) {
      if (Math.abs(a[i] - a[j]) <= d && dp[j] + a[i] > dp[i]) {
        dp[i] = dp[j] + a[i];
        par[i] = j;
      }
    }
    if (dp[i] > best) {
      best = dp[i];
      bestIdx = i;
    }
  }

  // Reconstruct subsequence
  const seq = [];
  let curr = bestIdx;
  while (curr !== -1) {
    seq.push(curr);
    curr = par[curr];
  }
  return { maxSum: best, subsequence: seq.reverse() };
}
```

## Time/Space Complexity
Time: O(n²) due to nested loops checking all previous indices
Space: O(n) for dp and parent arrays

## Why This Is Asked
This tests fixed-length path DP and path reconstruction in graphs, a core DP pattern that shows depth beyond standard knapsack.

## Key Concepts
- DP on path length t
- State transition using edges
- Backpointer reconstruction
- Time and space trade-offs

## Code Example
```javascript
function maxKEdgePath(n, edges, k) {
  const NEG = -Infinity;
  const dp = Array.from({length: n}, () => Array(k+1).fill(NEG));
  const par = Array.from({length: n}, () => Array(k+1).fill(-1));
  for (let v=0; v<n; v++) dp[v][0] = 0;
  for (let t=1; t<=k; t++) {
    for (const e of edges) {
      const {u,v,w} = e;
      const prev = dp[u][t-1];
      if (prev !== NEG) {
        const cand = prev + w;
        if (cand > dp[v][t]) {
          dp[v][t] = cand;
          par[v][t] = u;
        }
      }
    }
  }
  let bestV = 0, best = NEG;
  for (let v=0; v<n; v++) if (dp[v][k] > best) { best = dp[v][k]; bestV = v; }
  const path = [];
  let cur = bestV;
  for (let t=k; t>=1; t--) { path.push(cur); cur = par[cur][t]; }
  path.push(cur);
  path.reverse();
  return {path, weight: best};
}
```

## Follow-up Questions
- How would this change if edges could have negative weights? How to handle ties in reconstruction?

## How It Works

Concise technical explanation of the mechanism.

## Key Points

- **DP State**: local[k], global[k] track ending vs non-ending subarrays
- **Transition**: local[k] = max(local[k]+a[i], global[k-1]+a[i]); global[k] = max(global[k], local[k])
- **Edge Handling**: cap K to n; initialize -inf; handles negative values

## Example

```javascript
function maxRevenue(A, K) {
  const n = A.length;
  if (n === 0 || K <= 0) return 0;
  K = Math.min(K, n);
  const global = new Array(K+1).fill(-Infinity);
  const local = new Array(K+1).fill(-Infinity);
  global[0] = 0;
  for (let x of A) {
    for (let k = K; k >= 1; k--) {
      local[k] = Math.max((local[k] !== -Infinity ? local[k] + x : -Infinity), global[k-1] + x);
      global[k] = Math.max(global[k], local[k]);
    }
  }
  return global[K];
}
```

## Why This Is Asked
This problem tests your ability to structure a dynamic programming solution for exact-k resource selection with non-overlapping intervals. It requires combining weighted interval scheduling with a prefix DP over both task count and index, along with binary search for efficient predecessor lookup and clean reconstruction.

## Key Concepts
- Weighted interval scheduling with exact k constraint
- Prefix DP over tasks (i) and count (t)
- Precomputing p[i] via binary search for O(log n) lookups
- Backtracking through DP table for reconstruction

## Code Example
```javascript
function weightedIntervalScheduling(tasks, K) {
  // Sort by end time
  tasks.sort((a, b) => a.end - b.end);
  const n = tasks.length;

  // Precompute p[i] - last non-overlapping task
  const ends = tasks.map(t => t.end);
  const p = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    let lo = 0, hi = i - 1, res = -1;
    while (lo <= hi) {
      const mid = Math.floor) / 2((lo + hi);
      if (tasks[mid].end <= tasks[i].start) {
        res = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    p[i] = res;
  }

  // DP table: dp[i][t] = max value using first i tasks for t selections
  const dp = Array.from({ length: n + 1 }, () => Array(K + 1).fill(0));

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= K; t++) {
      // Skip task i-1
      dp[i][t] = dp[i - 1][t];
      // Take task i-1
      if (p[i - 1] !== -1) {
        dp[i][t] = Math.max(dp[i][t], dp[p[i - 1] + 1][t - 1] + tasks[i - 1].value);
      } else if (t === 1) {
        dp[i][t] = Math.max(dp[i][t], tasks[i - 1].value);
      }
    }
  }

  // Reconstruction
  const chosen = [];
  let i = n, t = K;
  while (i > 0 && t > 0) {
    if (dp[i][t] === dp[i - 1][t]) {
      i--;
    } else {
      chosen.push(i - 1);
      const prev = p[i - 1];
      i = prev + 1;
      t--;
    }
  }

  return { maxValue: dp[n][K], chosenTasks: chosen.reverse() };
}
```

## Why This Is Asked
Tests ability to extend DP with a cooldown constraint and to backtrack trades.

## Key Concepts
- Multi-state DP with cooldown
- 1-based transaction counting, backtracking
- Space optimization via rolling arrays

## Code Example
```javascript
function maxProfitWithCooldown(prices, k) {
  const n = prices.length; if (!n || k===0) return 0;
  const NEG = -1e15;
  let no = new Array(k+1).fill(0);
  let hold = new Array(k+1).fill(NEG);
  let cool = new Array(k+1).fill(NEG);
  hold[0] = -prices[0];
  for (let i=1;i<n;i++){
    let nno=no.slice(), nhold=hold.slice(), ncool=cool.slice();
    for (let t=0;t<=k;t++){
      nno[t] = Math.max(nno[t], cool[t]);
      nhold[t] = Math.max(nhold[t], no[t] - prices[i]);
      if (t>0) ncool[t] = Math.max(ncool[t], hold[t-1] + prices[i]);
    }
    no=nno; hold=nhold; cool=ncool;
  }
  let best=0; for (let t=0;t<=k;t++) best=Math.max(best,no[t],cool[t]);
  return best;
}
```

